/* Regulasi Hub Styling */
.reg-hero {
    background: linear-gradient(135deg, #0f5132 0%, #157347 100%);
    color: #ffffff;
    padding: 60px 0 50px;
    text-align: center;
}
.reg-hero h1 {
    font-size: clamp(1.8rem, 3.5vw, 2.7rem);
    font-weight: 800;
    margin: 0 0 14px;
    line-height: 1.25;
}
.reg-hero p {
    font-size: 1.05rem;
    opacity: 0.9;
    max-width: 720px;
    margin: 0 auto 28px;
    line-height: 1.6;
}
.reg-stats-row {
    display: flex;
    justify-content: center;
    gap: 32px;
    flex-wrap: wrap;
    margin-top: 24px;
}
.reg-stat-box {
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 12px;
    padding: 12px 24px;
    min-width: 140px;
}
.reg-stat-box strong {
    display: block;
    font-size: 1.8rem;
    font-weight: 800;
    color: #ffd166;
}
.reg-stat-box span {
    font-size: 0.85rem;
    opacity: 0.9;
}

/* Search bar */
.reg-search-form {
    background: #ffffff;
    border-radius: 12px;
    padding: 6px;
    display: flex;
    gap: 8px;
    max-width: 640px;
    margin: 0 auto;
    box-shadow: 0 8px 24px rgba(0,0,0,0.18);
}
.reg-search-form input {
    flex: 1;
    border: none;
    outline: none;
    padding: 12px 18px;
    font-size: 1rem;
    color: #1f2937;
    background: transparent;
}
.reg-search-form button {
    background: var(--orange, #f97316);
    color: #ffffff;
    border: none;
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 700;
    cursor: pointer;
    transition: background 0.2s;
}
.reg-search-form button:hover {
    background: #ea580c;
}

/* Filter Section */
.reg-filter-bar {
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    padding: 18px 0;
}
.reg-filter-group {
    margin-bottom: 10px;
}
.reg-filter-group:last-child {
    margin-bottom: 0;
}
.reg-filter-label {
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #64748b;
    margin-bottom: 6px;
    letter-spacing: 0.05em;
}
.reg-chip-row {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    align-items: center;
}
.reg-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 14px;
    border-radius: 999px;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #334155;
    font-size: 0.85rem;
    font-weight: 500;
    text-decoration: none;
    transition: all 0.2s ease;
}
.reg-chip:hover {
    border-color: #0f5132;
    color: #0f5132;
}
.reg-chip.active {
    background: #0f5132;
    color: #ffffff;
    border-color: #0f5132;
    font-weight: 600;
}

/* Regulation Cards Grid */
.reg-main-content {
    padding: 44px 0 60px;
}
.reg-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 24px;
}
.reg-card {
    background: #ffffff;
    border-radius: 12px;
    border: 1px solid #e2e8f0;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.reg-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.08);
}
.reg-card-header {
    padding: 16px 20px;
    border-bottom: 1px solid #f1f5f9;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.reg-badge-type {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 6px;
    letter-spacing: 0.03em;
}
.badge-uu { background: #dcfce7; color: #15803d; }
.badge-pp { background: #dbeafe; color: #1e40af; }
.badge-permenaker { background: #ffedd5; color: #c2410c; }
.badge-kepmenaker { background: #f3e8ff; color: #7e22ce; }
.badge-esdm { background: #fef3c7; color: #b45309; }
.badge-lhk { background: #ccfbf1; color: #0f766e; }
.badge-iso { background: #e0e7ff; color: #4338ca; }

.reg-year {
    font-size: 0.85rem;
    font-weight: 600;
    color: #64748b;
}
.reg-card-body {
    padding: 20px;
    flex: 1;
    display: flex;
    flex-direction: column;
}
.reg-card-title {
    font-size: 1.15rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 8px;
    line-height: 1.35;
}
.reg-card-tentang {
    font-size: 0.92rem;
    font-weight: 600;
    color: #0f5132;
    margin: 0 0 12px;
    line-height: 1.4;
}
.reg-card-summary {
    font-size: 0.875rem;
    color: #475569;
    line-height: 1.55;
    margin: 0 0 16px;
    flex: 1;
}
.reg-card-footer {
    padding-top: 14px;
    border-top: 1px solid #f1f5f9;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.reg-cat-tag {
    font-size: 0.78rem;
    font-weight: 600;
    color: #64748b;
    background: #f1f5f9;
    padding: 3px 8px;
    border-radius: 4px;
}
.reg-link-btn {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f5132;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
.reg-link-btn:hover {
    color: var(--orange, #f97316);
    text-decoration: underline;
}

/* Featured Training Hub Section */
.featured-pelatihan-section {
    background: #f1f5f9;
    padding: 56px 0 64px;
    border-top: 1px solid #e2e8f0;
}
.featured-section-title {
    text-align: center;
    margin-bottom: 36px;
}
.featured-section-title h2 {
    font-size: 1.85rem;
    font-weight: 800;
    color: #0f172a;
    margin: 0 0 8px;
}
.featured-section-title p {
    font-size: 1rem;
    color: #64748b;
    max-width: 600px;
    margin: 0 auto;
}
.featured-training-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
}
.ft-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 24px;
    border: 1px solid #cbd5e1;
    display: flex;
    flex-direction: column;
    box-shadow: 0 2px 6px rgba(0,0,0,0.04);
}
.ft-badge {
    display: inline-block;
    background: #dcfce7;
    color: #166534;
    font-size: 0.75rem;
    font-weight: 700;
    padding: 3px 8px;
    border-radius: 4px;
    margin-bottom: 12px;
    align-self: flex-start;
}
.ft-title {
    font-size: 1.05rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 8px;
    line-height: 1.35;
}
.ft-desc {
    font-size: 0.85rem;
    color: #64748b;
    line-height: 1.5;
    margin: 0 0 16px;
    flex: 1;
}
.ft-btn {
    display: block;
    text-align: center;
    background: #0f5132;
    color: #ffffff;
    font-weight: 700;
    font-size: 0.88rem;
    padding: 10px 16px;
    border-radius: 8px;
    text-decoration: none;
    transition: background 0.2s;
}
.ft-btn:hover {
    background: var(--orange, #f97316);
}
